class Solution {
    int MOD = 1000000007;
    int memo[1000][1000];
    int dp(int i, int j, const string& s) {
        if (i > j) return 0;
        if (i == j) return 1;
        if (memo[i][j] != -1) return memo[i][j];
        long long ans = 0;
        for (char ch : {'a', 'b', 'c', 'd'}) {
            int left = -1, right = -1;
            for (int k = i; k <= j; k++) if (s[k] == ch) { left = k; break; }
            for (int k = j; k >= i; k--) if (s[k] == ch) { right = k; break; }
            if (left == -1) continue;
            if (left == right) ans = (ans + 1) % MOD;
            else ans = (ans + 2 + dp(left + 1, right - 1, s)) % MOD;
        }
        return memo[i][j] = ans;
    }
public:
    int countPalindromicSubsequences(string s) {
        memset(memo, -1, sizeof(memo));
        return dp(0, s.size() - 1, s);
    }
};

class Solution {
    private int MOD = 1_000_000_007;
    private Integer[][] memo;
    public int countPalindromicSubsequences(String s) {
        int n = s.length();
        memo = new Integer[n][n];
        return dp(0, n - 1, s);
    }
    private int dp(int i, int j, String s) {
        if (i > j) return 0;
        if (i == j) return 1;
        if (memo[i][j] != null) return memo[i][j];
        long ans = 0;
        char[] chars = {'a', 'b', 'c', 'd'};
        for (char ch : chars) {
            int left = -1, right = -1;
            for (int k = i; k <= j; k++) if (s.charAt(k) == ch) { left = k; break; }
            for (int k = j; k >= i; k--) if (s.charAt(k) == ch) { right = k; break; }
            if (left == -1) continue;
            if (left == right) ans = (ans + 1) % MOD;
            else ans = (ans + 2 + dp(left + 1, right - 1, s)) % MOD;
        }
        return memo[i][j] = (int) ans;
    }
}

var countPalindromicSubsequences = function(s) {
    const MOD = 1000000007;
    const memo = new Map();
    function dp(i, j) {
        if (i > j) return 0;
        if (i === j) return 1;
        const key = (i << 12) | j;
        if (memo.has(key)) return memo.get(key);
        let ans = 0;
        for (const ch of ['a', 'b', 'c', 'd']) {
            const left = s.indexOf(ch, i);
            if (left === -1 || left > j) continue;
            const right = s.lastIndexOf(ch, j);
            if (right === -1 || right < i) continue;
            if (left === right) ans = (ans + 1) % MOD;
            else ans = (ans + 2 + dp(left + 1, right - 1)) % MOD;
        }
        memo.set(key, ans);
        return ans;
    }
    return dp(0, s.length - 1);
};
